    /// <summary>
    /// The attribute container for the ManifestGenerator details. Jobs must be created with either a manifest file or a ManifestGenerator, but not both. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: S3JobManifestGenerator. S3JobManifestGenerator -&gt; (structure) The S3 job ManifestGenerator's configuration details. ExpectedBucketOwner -&gt; (string) The Amazon Web Services account ID that owns the source bucket specified in SourceBucket . If provided, the manifest source bucket owner's Amazon Web Services account ID must match this value, else the job fails. Constraints: o max: 64 o pattern: ^\d{12}$ SourceBucket -&gt; (string) [required] The ARN of the source bucket used by the ManifestGenerator. NOTE: Directory buckets - Directory buckets aren't supported as the source buckets used by S3JobManifestGenerator to gen- erate the job manifest. Constraints: o min: 1 o max: 128 o pattern: arn:[^:]+:s3:.* ManifestOutputLocation -&gt; (structure) Specifies the location the generated manifest will be written to. Manifests can't be written to directory buckets. For more information, see Directory buckets . ExpectedManifestBucketOwner -&gt; (string) The Account ID that owns the bucket the generated mani- fest is written to. Constraints: o max: 64 o pattern: ^\d{12}$ Bucket -&gt; (string) [required] The bucket ARN the generated manifest should be written to. NOTE: Directory buckets - Directory buckets aren't supported as the buckets to store the generated manifest. Constraints: o min: 1 o max: 128 o pattern: arn:[^:]+:s3:.* ManifestPrefix -&gt; (string) Prefix identifying one or more objects to which the mani- fest applies. Constraints: o min: 1 o max: 512 ManifestEncryption -&gt; (structure) Specifies what encryption should be used when the gener- ated manifest objects are written. SSES3 -&gt; (structure) Specifies the use of SSE-S3 to encrypt generated mani- fest objects. SSEKMS -&gt; (structure) Configuration details on how SSE-KMS is used to en- crypt generated manifest objects. KeyId -&gt; (string) [required] Specifies the ID of the Amazon Web Services Key Management Service (Amazon Web Services KMS) sym- metric encryption customer managed key to use for encrypting generated manifest objects. Constraints: o min: 1 o max: 2000 ManifestFormat -&gt; (string) [required] The format of the generated manifest. Possible values: o S3InventoryReport_CSV_20211130 Filter -&gt; (structure) Specifies rules the S3JobManifestGenerator should use to de- cide whether an object in the source bucket should or should not be included in the generated job manifest. EligibleForReplication -&gt; (boolean) Include objects in the generated manifest only if they are eligible for replication according to the Replication configuration on the source bucket. CreatedAfter -&gt; (timestamp) If provided, the generated manifest includes only source bucket objects that were created after this time. CreatedBefore -&gt; (timestamp) If provided, the generated manifest includes only source bucket objects that were created before this time. ObjectReplicationStatuses -&gt; (list) If provided, the generated manifest includes only source bucket objects that have one of the specified Replication statuses. (string) Possible values: o COMPLETED o FAILED o REPLICA o NONE KeyNameConstraint -&gt; (structure) If provided, the generated manifest includes only source bucket objects whose object keys match the string con- straints specified for MatchAnyPrefix , MatchAnySuffix , and MatchAnySubstring . MatchAnyPrefix -&gt; (list) If provided, the generated manifest includes objects where the specified string appears at the start of the object key string. Each KeyNameConstraint filter ac- cepts an array of strings with a length of 1 string. (string) Constraints: o min: 1 o max: 1024 MatchAnySuffix -&gt; (list) If provided, the generated manifest includes objects where the specified string appears at the end of the object key string. Each KeyNameConstraint filter ac- cepts an array of strings with a length of 1 string. (string) Constraints: o min: 1 o max: 1024 MatchAnySubstring -&gt; (list) If provided, the generated manifest includes objects where the specified string appears anywhere within the object key string. Each KeyNameConstraint filter ac- cepts an array of strings with a length of 1 string. (string) Constraints: o min: 1 o max: 1024 ObjectSizeGreaterThanBytes -&gt; (long) If provided, the generated manifest includes only source bucket objects whose file size is greater than the speci- fied number of bytes. ObjectSizeLessThanBytes -&gt; (long) If provided, the generated manifest includes only source bucket objects whose file size is less than the specified number of bytes. MatchAnyStorageClass -&gt; (list) If provided, the generated manifest includes only source bucket objects that are stored with the specified storage class. (string) Possible values: o STANDARD o STANDARD_IA o ONEZONE_IA o GLACIER o INTELLIGENT_TIERING o DEEP_ARCHIVE o GLACIER_IR MatchAnyObjectEncryption -&gt; (list) If provided, the generated object list includes only source bucket objects with the indicated server-side en- cryption type (SSE-S3, SSE-KMS, DSSE-KMS, SSE-C, or NOT-SSE). Constraints: o min: 1 o max: 1 (tagged union structure) An optional filter for the S3JobManifestGenerator that identifies the subset of objects by encryption type. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: SSES3, SSEKMS, DSSEKMS, SSEC, NOTSSE. SSES3 -&gt; (structure) Filters for objects that are encrypted by server-side encryption with Amazon S3 managed keys (SSE-S3). SSEKMS -&gt; (structure) Filters for objects that are encrypted by server-side encryption with Amazon Web Services Key Management Service (KMS) keys (SSE-KMS). KmsKeyArn -&gt; (string) The Amazon Resource Name (ARN) of the customer managed KMS key to use for the filter to return objects that are encrypted by the specified key. For best performance, use keys in the same Region as the S3 Batch Operations job. Constraints: o min: 20 o max: 2048 o pattern: arn:aws[a-zA-Z0-9-]*:kms:[a-z0-9-]+:[0-9]{12}:key/[a-zA-Z0-9-]+ BucketKeyEnabled -&gt; (boolean) Specifies whether Amazon S3 should use an S3 Bucket Key for object encryption with server-side encryption using Amazon Web Ser- vices Key Management Service (Amazon Web Ser- vices KMS) keys (SSE-KMS). If specified, will filter SSE-KMS encrypted objects by S3 Bucket Key status. DSSEKMS -&gt; (structure) Filters for objects that are encrypted by dual-layer server-side encryption with Amazon Web Services Key Management Service (KMS) keys (DSSE-KMS). KmsKeyArn -&gt; (string) The Amazon Resource Name (ARN) of the customer managed KMS key to use for the filter to return objects that are encrypted by the specified key. For best performance, use keys in the same Region as the S3 Batch Operations job. Constraints: o min: 20 o max: 2048 o pattern: arn:aws[a-zA-Z0-9-]*:kms:[a-z0-9-]+:[0-9]{12}:key/[a-zA-Z0-9-]+ SSEC -&gt; (structure) Filters for objects that are encrypted by server-side encryption with customer-provided keys (SSE-C). NOTSSE -&gt; (structure) Filters for objects that are not encrypted by server-side encryption. EnableManifestOutput -&gt; (boolean) [required] Determines whether or not to write the job's generated mani- fest to a bucket. JSON Syntax: { "S3JobManifestGenerator": { "ExpectedBucketOwner": "string", "SourceBucket": "string", "ManifestOutputLocation": { "ExpectedManifestBucketOwner": "string", "Bucket": "string", "ManifestPrefix": "string", "ManifestEncryption": { "SSES3": { }, "SSEKMS": { "KeyId": "string" } }, "ManifestFormat": "S3InventoryReport_CSV_20211130" }, "Filter": { "EligibleForReplication": true|false, "CreatedAfter": timestamp, "CreatedBefore": timestamp, "ObjectReplicationStatuses": ["COMPLETED"|"FAILED"|"REPLICA"|"NONE", ...], "KeyNameConstraint": { "MatchAnyPrefix": ["string", ...], "MatchAnySuffix": ["string", ...], "MatchAnySubstring": ["string", ...] }, "ObjectSizeGreaterThanBytes": long, "ObjectSizeLessThanBytes": long, "MatchAnyStorageClass": ["STANDARD"|"STANDARD_IA"|"ONEZONE_IA"|"GLACIER"|"INTELLIGENT_TIERING"|"DEEP_ARCHIVE"|"GLACIER_IR", ...], "MatchAnyObjectEncryption": [ { "SSES3": { }, "SSEKMS": { "KmsKeyArn": "string", "BucketKeyEnabled": true|false }, "DSSEKMS": { "KmsKeyArn": "string" }, "SSEC": { }, "NOTSSE": { } } ... ] }, "EnableManifestOutput": true|false } }
    /// </summary>
    [CliOption("--manifest-generator")]
    public string? ManifestGenerator { get; set; }

    [CliOption("--cli-input-json")]
